-- Original Ace Student applied revision questions; illustrative concepts, not copied institutional exam papers.
insert into public.ace_quizzes(title,course_code,description) select 'Cost Accounting · Decisions and Variances','BFC3227','Applied budgeting, cost-volume-profit analysis, overheads and production decisions.' where not exists(select 1 from public.ace_quizzes where title='Cost Accounting · Decisions and Variances');
with target as (select id from public.ace_quizzes where title='Cost Accounting · Decisions and Variances' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('A product sells for KSh 800 with variable cost KSh 500. What is contribution per unit?','["KSh 300","KSh 500","KSh 800","KSh 1,300"]',0,'Contribution per unit equals selling price minus variable cost: 800 − 500 = KSh 300.',1),('Monthly fixed costs are KSh 90,000 and contribution per unit is KSh 300. What is break-even sales volume?','["90 units","200 units","300 units","900 units"]',2,'Break-even units = fixed costs / unit contribution = 90,000 / 300 = 300.',2),('Actual direct material cost exceeds the standard cost for the actual output. The cost variance is:','["Favourable","Unfavourable","Always zero","Revenue"]',1,'Spending more than the standard cost for actual output gives an unfavourable cost variance.',3),('Which cost is typically relevant to accepting a one-off order when idle capacity exists?','["Incremental variable production cost","Historical equipment purchase price","Last year''s sunk market research cost","Already incurred rent"]',0,'Incremental costs change because of the decision; sunk or unavoidable past costs do not.',4),('Opening inventory is 100 units; 400 units are produced and 450 are sold. Closing inventory is:','["50 units","150 units","850 units","350 units"]',0,'Closing inventory = opening inventory + production − units sold = 100 + 400 − 450 = 50.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;
insert into public.ace_quizzes(title,course_code,description) select 'Human Resource Management · Applied Practice','BFB3200','Scenario-based performance, recruitment, employee development and workplace fairness.' where not exists(select 1 from public.ace_quizzes where title='Human Resource Management · Applied Practice');
with target as (select id from public.ace_quizzes where title='Human Resource Management · Applied Practice' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('A business interviews all applicants with the same job-related questions and scoring rubric. This most directly improves:','["Consistency in candidate evaluation","Guaranteed elimination of bias","Sales forecasting","Office inventory"]',0,'Structured interviews improve consistency, though they do not eliminate all forms of bias.',1),('After training, an employee handles customer complaints more accurately. Which measure best evaluates training outcomes?','["Observed job performance after training","Number of posters printed","Only the trainer''s speaking time","The price of the training room"]',0,'Post-training performance is closer to the desired workplace outcome.',2),('A staff member repeatedly misses targets because the process instructions are unclear. The supervisor''s most useful first action is:','["Clarify expectations and diagnose barriers","Issue dismissal without investigation","Reduce everyone''s pay","Ignore the issue"]',0,'Clarification and root-cause analysis should precede an appropriate response.',3),('An exit interview is most useful for:','["Learning why employees leave and identifying possible improvements","Replacing all attendance records","Setting exchange rates","Avoiding all employee conversations"]',0,'Exit interviews can surface patterns in management, work conditions and retention.',4),('A job description normally emphasizes:','["Duties and responsibilities","The employee''s favorite hobbies","Expected company share prices","Only the owner''s biography"]',0,'A job description outlines work tasks, reporting relationships and responsibilities.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;
insert into public.ace_quizzes(title,course_code,description) select 'Business Law · Practical Reasoning','BFB3201','Illustrative general business-law principles; not a substitute for Kenyan legal advice.' where not exists(select 1 from public.ace_quizzes where title='Business Law · Practical Reasoning');
with target as (select id from public.ace_quizzes where title='Business Law · Practical Reasoning' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('Two businesses agree on price and delivery but disagree later about specifications. Which preventive measure would have been strongest?','["Record clear product specifications and acceptance criteria","Rely entirely on assumptions","Avoid keeping any contract records","Let either side change terms secretly"]',0,'Written specifications and clear acceptance criteria help reduce ambiguity.',1),('A person signs a supply agreement on behalf of a company without authority. What should the company investigate first?','["Whether the person had actual or apparent authority","Whether the signature was written in blue ink","How many likes the supplier has online","Whether the office is on the ground floor"]',0,'Authority is central to deciding whether an agent''s actions can bind a principal.',2),('A business receives confidential customer records from a supplier. A prudent next step is to:','["Restrict access and comply with applicable data protection obligations","Post records in the class group","Sell the list without checking permission","Ignore how information is stored"]',0,'Confidential information should be handled securely and consistently with applicable law and permissions.',3),('A product advertisement is misleading about a material feature. Which general legal area is most relevant?','["Consumer protection and fair trading","Land inheritance only","Shipping insurance only","Corporate dividend calculation"]',0,'Misleading commercial claims commonly raise consumer-protection and fair-trading issues; details depend on jurisdiction.',4),('A supplier cannot deliver on time. Before claiming a remedy, the buyer should examine:','["The agreed terms, exceptions and applicable law","Only the supplier''s brand colors","Whether the buyer follows the supplier online","Unrelated competitor salaries"]',0,'Contractual obligations and applicable law determine available rights and remedies.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;
insert into public.ace_quizzes(title,course_code,description) select 'Entrepreneurship · Customer and Cash Flow','BFB3202','Evidence-led customer discovery, unit economics, feasibility and cash management.' where not exists(select 1 from public.ace_quizzes where title='Entrepreneurship · Customer and Cash Flow');
with target as (select id from public.ace_quizzes where title='Entrepreneurship · Customer and Cash Flow' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('A bakery sells each cake for KSh 1,200 and pays KSh 750 in variable costs. What is the contribution per cake?','["KSh 450","KSh 750","KSh 1,200","KSh 1,950"]',0,'1,200 − 750 = KSh 450 contribution available for fixed costs and profit.',1),('A founder talks to ten potential customers. Which response is strongest evidence of demand?','["Three make a deposit for a specific product","Eight say the idea sounds nice","Nine like the logo","Ten follow a social account"]',0,'Financial commitment usually provides stronger validation than compliments alone.',2),('Customers pay 30 days after delivery but suppliers demand cash immediately. The main operational risk is:','["Cash-flow mismatch","Too little brand awareness in every case","An incorrect product name","A lower accounting depreciation rate"]',0,'Cash collections arriving after expenses can create working-capital stress.',3),('Monthly fixed overhead is KSh 18,000; contribution per sale is KSh 600. How many sales are needed to break even?','["12","18","30","60"]',2,'Break-even sales = 18,000 / 600 = 30.',4),('A shop wants to test two prices ethically. What should it compare alongside revenue?','["Conversion, contribution margin and customer response","Only the number of people walking past","Just the color of the signage","The price of unrelated groceries"]',0,'Revenue alone can hide changes in margin or demand; evaluate useful commercial outcomes.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;
insert into public.ace_quizzes(title,course_code,description) select 'Leadership · Conflict and Execution','BFB3203','Team decision-making, delegation, accountability and practical feedback.' where not exists(select 1 from public.ace_quizzes where title='Leadership · Conflict and Execution');
with target as (select id from public.ace_quizzes where title='Leadership · Conflict and Execution' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('Two project members disagree over the order of tasks. A leader should first:','["Surface constraints and agree on prioritization criteria","Ignore both students","Choose the loudest voice automatically","Delete the project"]',0,'Shared criteria such as deadlines, dependencies and impact help resolve task priorities.',1),('A delegated task fails because no owner or deadline was defined. The missing element is:','["Clear accountability","More office decoration","An extra social-media post","A larger meeting room"]',0,'Delegation works better when ownership, deadlines, authority and outputs are explicit.',2),('A team leader notices that quieter members rarely speak. Which action best improves inclusion?','["Invite written input and rotate speaking opportunities","Assume silence means agreement","Only ask the most senior member","Cancel all feedback channels"]',0,'Multiple avenues for participation improve the chance of hearing diverse contributions.',3),('After a project setback, the best first review question is:','["What happened, why, and what can we change?","Who can we blame publicly?","How can we remove every written record?","Why should we stop measuring results?"]',0,'Evidence-based reflection helps teams learn and improve systems.',4),('A project is behind schedule. What information is most useful before reallocating people?','["Critical tasks, dependencies and skills needed","Each member''s favorite music","The team''s profile pictures","The brand''s original founding date"]',0,'Task dependencies and competencies determine where additional effort can improve delivery.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;
insert into public.ace_quizzes(title,course_code,description) select 'Public Relations · Campaign Analysis','BFB3205','Stakeholder mapping, messaging, responsible media relations and campaign evaluation.' where not exists(select 1 from public.ace_quizzes where title='Public Relations · Campaign Analysis');
with target as (select id from public.ace_quizzes where title='Public Relations · Campaign Analysis' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('An awareness campaign reaches 10,000 people, but few recall its message. Which conclusion is most appropriate?','["Reach alone did not establish understanding","The campaign definitely changed behavior","All recipients understood the message","Message recall should never be measured"]',0,'Exposure and understanding are different outcomes; evaluate recall and comprehension separately.',1),('A student club faces a false rumour circulating online. What should the communication team do first?','["Verify facts and issue an accurate, proportionate response","Repeat the rumour as proven truth","Publish personal information about the critic","Invent evidence to support its position"]',0,'Fact-checking supports credible and proportionate crisis communication.',2),('What is a stakeholder map primarily used for?','["Identifying groups affected by or able to influence an initiative","Calculating monthly depreciation","Choosing a bank interest rate","Recording warehouse stock movements"]',0,'Stakeholder mapping informs whom to engage and how.',3),('A press release announces a new university study clinic. The opening paragraph should emphasize:','["The most newsworthy facts: what, when, where and why it matters","All staff biographies before the main story","Only decorative quotes","Unverified rumours"]',0,'Leading with essential accurate facts helps journalists and audiences understand the story.',4),('A campaign promises weekly updates on a student issue. Trust is most likely to improve when organizers:','["Report progress consistently, including setbacks","Publish only when everything goes perfectly","Change commitments without explanation","Ignore requests for accountability"]',0,'Transparent follow-through and accurate updates help build credibility.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;
